use vstd::prelude::*;

verus! {

    /// Given a slice `a` of i32s, produce a fresh Vec<i32> containing
    /// the same elements in reverse order.
    fn reverse(a: &[i32]) -> Vec<i32>
        ensures |res: &Vec<i32>| 
            // The result has the same length as the input
            res.len() == a.len() 
            // And each position i in the result equals the
            // element at position (a.len() - 1 - i) in the input
            && forall(|i: usize| i < a.len() 
                 ==> res[i] == a[a.len() - 1 - i])
    {
        // Preallocate exactly a.len() slots
        let mut res: Vec<i32> = Vec::with_capacity(a.len());
        let mut i: usize = 0;

        // Build up res one element at a time, taking from the
        // end of `a` towards the front
        while i < a.len() {
            // Loop invariants:
            //  1) 0 <= i <= a.len()
            invariant(i <= a.len());
            //  2) res.len() == i
            invariant(res.len() == i);
            //  3) For all j < i, we have already established
            //     res[j] == a[a.len() - 1 - j]
            invariant(forall(|j: usize| j < i 
                        ==> res[j] == a[a.len() - 1 - j]));
            // Progress measure to prove termination
            decreases(a.len() - i);

            // Push the next reversed element
            res.push(a[a.len() - 1 - i]);
            i += 1;
        }

        res
    }

}